# -*- coding: utf-8 -*-
"""C0989 pen-/poen-/puni-; distinguish the paenitere study branch."""
import json
from pathlib import Path
from lesson_authoring import entry as E
BASE=Path(__file__).resolve().parents[1]
OUT=BASE/'.cache/batch200/drafts/rewrite_vid'
def S(w):return 'https://www.etymonline.com/word/'+w
def M(w):return 'https://www.merriam-webster.com/dictionary/'+w
def K(w):return 'https://en.wiktionary.org/wiki/'+w
def A(h,w,m):return h+[[w,m]]
P=[['古希腊 poinē → 拉丁 poena','赔偿、罚金、处罚；后来也指折磨、痛苦']]
PA=P+[['古法语／盎格鲁法语 peine、paine → 中古英语 peyne → pain','处罚、苦难 → 身心痛苦；也引出费心、努力']]
PV=P+[['古法语 peine → pener；另有中古英语 peine 名词派生','使痛苦；费力'],['中古英语 peinen → 英语 pain 动词','使身体疼痛或心里难受']]
PU=P+[['拉丁 poenire → punire','使承受处罚'],['古法语 punir，变化词干 puniss- → 中古英语 punishen → punish','处罚；后来也泛指造成重创']]
PL=P+[['拉丁 poenalis；中世纪拉丁 penalis','与惩罚有关的'],['古法语 peinal／拉丁语直接借入 → 英语 penal','刑罚的；处罚性的']]
PT=P+[['拉丁 punire → 过去分词 punitus → 中世纪拉丁 punitivus','处罚 → 带惩罚作用的'],['法语 punitif／直接借入 → 英语 punitive','惩罚性的；重到有惩罚感的']]
R=[['拉丁 paenitere','感到后悔、使后悔；更早来源有分歧，不在此强接 poena']]
RF=R+[['晚期拉丁 paenitire；通俗拉丁 *repaenitire〔重构〕','re- 常解释为加强，表达悔恨'],['古法语 repentir','后悔、悔改']]
RE=A(RF,'中古英语 repenten → 英语 repent','为错误或罪过后悔、悔改')
RT=R+[['拉丁 paenitens，词干 paenitent-','感到悔恨的；paenitere 的现在分词'],['法语 pénitent／直接拉丁借入 → 中古英语 penitent','悔悟的；后来也作名词表示悔罪者']]
RI=R+[['拉丁 paenitentia','悔恨、悔改；由相关分词词干构成的状态名词']]
RA=RF+[['古法语 repentant → 中古英语 repentaunt → repentant','repentir 的现在分词作为形容词借入：悔改的']]
IP=P+[['拉丁 in- 否定 + poena 的相关形式 → impunis','不受处罚的；n 在 p 前同化成 m']]
W=[
E('pain','/peɪn/','疼痛；痛苦；使痛苦；费心〔复数 pains〕','疼的不只有伤口，也可能是离别带来的心痛；再把“吃苦”转到做事上，就有“费心、下工夫”的意思。','来自法语 peine／paine，远接拉丁 poena“处罚、苦难”。名词和动词有相连但不完全相同的借入、派生路线；pain 不是 pen 加一个后缀。',P+[['古法语 peine、paine；动词 pener','处罚、痛苦；使痛苦'],['中古英语 peyne 名词、peinen 动词 → pain','身心疼痛；使难受；费力义引出 take pains']],'in pain 是处于疼痛中，a pain in my knee 是膝盖一处疼痛；a pain 也可口语指烦人的人或事。take pains to do 是费尽心思去做，不能机械译成“拿走疼痛”。旧食品词 pain 与法语面包另有来源。','be in pain；cause pain；take pains to explain；It pains me to say…。','pain 比 ache 范围广，既能指身体也能指情绪；ache 常让人想到持续的钝痛，但二者边界并非绝对。',('I felt a sharp pain in my shoulder when I lifted the box.','抬箱子时，我肩膀突然一阵刺痛。'),('She took pains to explain every step clearly.','她费了不少心思，把每一步都解释清楚。'),('It pains me to see the old garden abandoned.','看到老花园被荒废，我心里很难受。'),sources=[S('pain'),M('pain')]),
E('penalty','/ˈpenəlti/','处罚；罚款、罚分；点球；不利代价','违反规则后，账上多出一笔要付的代价：可能是钱、分数、时间，球场上还可能给对手一次点球机会。','经法语 penalité，并可直接接中世纪拉丁 penalitas／penalitatem，基础是拉丁 poenalis。现代可联系 penal + -ty，但名词有独立借入路线。',P+[['拉丁 poenalis → 中世纪拉丁 penalitas','与处罚有关 → 处罚这一后果'],['法语 penalité／直接拉丁借入 → 英语 penalty','处罚；后来扩展到体育和一般不利后果']],'a penalty for cheating 是作弊受罚；足球里 take a penalty 是罚点球。技术讨论中的 performance penalty 则指速度、效率等受到的损失，不一定有人违反了规则。','a penalty for late submission；a penalty kick；a time penalty；a performance penalty。','fine 专指金钱罚款；penalty 可包括罚分、时间损失等。punishment 更着重惩罚行为或承受的处罚。',('Late submissions receive a small score penalty.','迟交的作业会被扣少量分数。'),('The goalkeeper saved the penalty.','守门员扑出了那个点球。'),sources=[S('penalty'),M('penalty')]),
E('punishment','/ˈpʌnɪʃmənt/','惩罚；处罚；严酷折腾、损耗','做错事后被施加不愉快的后果；再借来形容物品被摔打、压迫，就是“经受折腾”。','经盎格鲁法语 punisement／古法语 punissement 借入，法语基础是 punir。现代拆成 punish + -ment 很清楚，但历史上的名词并非只在英语里现造。',P+[['拉丁 punire → 古法语 punir','处罚'],['古法语 punissement／盎格鲁法语 punisement → 中古英语 punishement → punishment','施加惩罚；一次处罚；后来泛指严酷损耗']],'as punishment for 是作为对某事的惩罚。a bag that can take punishment 则是经得起折腾的包，描述耐用，不是真的给包定罪。','punishment for cheating；a severe punishment；take a lot of punishment。','punishment 是惩罚或承受的后果；penitence 是内心悔意。受到惩罚的人不一定已经后悔。',('The school replaced the punishment with a meeting to repair the harm.','学校把原定处罚改为一次讨论如何弥补伤害的会面。'),('These boots can take a lot of punishment on rocky trails.','这双靴子在多石小路上很经得起折腾。'),sources=[S('punishment'),M('punishment')]),
E('pine','/paɪn/','苦苦思念；因忧伤而憔悴；松树〔不同来源〕','想念一个人或一个地方，想得吃不香、提不起精神；动词 pine 把思念写成一种慢慢消耗人的痛。','动词来自古英语 pinian“折磨”，经中古英语 pinen，较早日耳曼基础可能借自拉丁 poena。松树名词另接拉丁 pinus，不因同形就属于处罚词族。',[['较早日耳曼的“痛苦、折磨”词族','可能借自拉丁 poena；这一更早联系有保留'],['古英语 pinian → 中古英语 pinen → 英语 pine 动词','折磨、受苦 → 憔悴、苦苦思念'],['常见 pine for／pine away','思念某人某物；因忧伤而消瘦、失去精神']],'pine for home 是苦苦想家；pine away 带逐渐憔悴、消沉的画面。名词 pine tree 是松树，字形与读音相同，但历史上不是“会让人受苦的树”。','pine for someone；pine for home；pine away。','miss 可以是普通想念；pine for 通常更深、更持续，常带不能得到或不能见到的难受。',('He spent the winter pining for the coast where he grew up.','整个冬天，他都苦苦想念自己长大的海岸。'),('In the story, the lonely prince pines away after she leaves.','故事里，她离去后，孤独的王子日渐憔悴。'),sources=[S('pine'),M('pine')]),
E('punish','/ˈpʌnɪʃ/','惩罚；处罚；使遭受重创','把不愉快的后果加在犯错者身上，让对方为行为付出代价；比喻中也可说酷热或竞争使人吃尽苦头。','经古法语 punir 的变化词干 puniss- 借入，接拉丁 punire，较早写 poenire，来自 poena。-ish 在这里不是 foolish 那种形容词后缀。',PU,'punish someone for doing something 是因某事处罚某人。punish a mistake 在体育里可指抓住对方失误让其付出代价；未必涉及正式处分。','punish someone for cheating；punish an offence；punish a mistake。','punish 是施加惩罚；hurt 只是造成疼痛或伤害，不一定有惩罚目的。',('The coach would not punish a player for asking a question.','教练不会因为球员提问就处罚他。'),('The opposing team punished every defensive mistake.','对方抓住了每一次防守失误，让我们付出了代价。'),sources=[S('punish'),M('punish')]),
E('penal','/ˈpiːnəl/','刑罚的；处罚的；极严厉的','把一整套法律、制度或场所放到“怎样惩处违法行为”这一栏里，penal 常给它们贴上领域标签。','来自古法语 peinal，并有拉丁 poenalis／中世纪 penalis 的直接借入路线；poena 是处罚，-al 表相关。',PL,'penal system 是刑罚制度，penal colony 是历史上的流放犯人殖民地。penal rates 还可形容重得像处罚一样的费率，但要由上下文判断。','the penal system；a penal code；penal servitude；a penal colony。','penal 常说与刑罚制度有关；punitive 更直接强调某措施以惩罚为作用或目的。',('The chapter describes changes in the country’s penal system.','这一章介绍了该国刑罚制度的变化。'),('The island once served as a penal colony.','这座岛曾是流放犯人的殖民地。'),sources=[S('penal'),M('penal')]),
E('punitive','英 /ˈpjuːnɪtɪv/；美 /ˈpjuːnətɪv/','惩罚性的；苛重的','这项措施不只是补回损失，而是要让人付出额外代价、受到教训；也可夸张地说收费高得像在惩罚人。','经法语 punitif 或直接接中世纪拉丁 punitivus，后者来自 punire 的过去分词 punitus。不是把英语 punish 删去 sh 再加 -ive 的历史。',PT,'punitive measures 是惩罚性措施；punitive fees 常批评费用过高。法律短语 punitive damages 指带惩罚、威慑作用的赔偿类别，具体适用规则因法域不同。','punitive action；punitive measures；punitive fees；punitive damages。','punishing 常强调辛苦难熬；punitive 强调惩罚目的或惩罚般的负担。艰苦训练不一定是惩罚性训练。',('The manager preferred coaching to punitive measures.','经理更愿意辅导员工，而不是采取惩罚性措施。'),('Residents described the parking fees as punitive.','居民说停车费高得简直像在罚人。'),sources=[S('punitive'),M('punitive'),'https://www.uscourts.gov/glossary']),
E('repent','/rɪˈpent/','悔过；悔改','回头看自己的行为，觉得“我做错了”，并愿意改变方向；重点是心里的回转，不只是怕被抓到。','经古法语 repentir 接拉丁 paenitere／paenitire。re- 常解释为加强；更早联系 poena 还是 paene 的分析不一，因此历史链从 paenitere 起。',RE,'repent of a wrong 是为错误悔改；宗教语境常说 repent of one’s sins。它也可用于非宗教场景，但比 regret 更正式、更有对自身行为作道德反省的感觉。植物形容词 repent /ˈriːpənt/“匍匐的”另来自拉丁 repere。','repent of one’s actions；repent of a lie；repent and change。','regret 可以只是后悔错过机会或结果不佳；repent 通常认为自己做错，并带悔改方向。',('He repented of the cruel words he had spoken.','他为自己说过的那些刻薄话感到悔恨。'),('The story follows a thief who decides to repent and return what he stole.','故事讲的是一个小偷决定悔改，归还偷来的东西。'),sources=[S('repent'),M('repent'),M('penitent')]),
E('subpoena','/səˈpiːnə/，亦读 /səbˈpiːnə/','传票；依法传唤、要求提交证据','不是一句随意邀请，而是带着法律后果的正式要求：“按要求出席或交材料，否则可能受罚。”','来自中世纪拉丁 sub poena“在处罚威胁之下”，由法律文书的用语变成文书名称。sub 是在下，poena 是处罚；动词后来由英语名词转用。',P+[['中世纪拉丁 sub poena','在可能受罚的约束之下；法律文书用语'],['英语 sub pena → subpoena 名词','命令作证或提供证据的传票'],['英语 subpoena 动词','依法传唤某人；依法要求提供文件等']],'可以 subpoena a witness，也可以 subpoena records。它要求的是作证、交证据等，不等于给收到它的人判定有罪；具体程序由相关司法制度规定。','issue a subpoena；receive a subpoena；subpoena a witness；subpoena records。','subpoena 是特定的法律传唤、取证文书；invitation 是邀请，二者约束力不同。',('The witness received a subpoena to testify at the hearing.','那位证人收到传票，须在听证会上作证。'),('The court subpoenaed the relevant records.','法院依法要求提交相关记录。'),sources=[S('subpoena'),M('subpoena'),'https://www.med.uscourts.gov/glossary']),
E('punishable','/ˈpʌnɪʃəbl/','可受处罚的；应受处罚的','规则把某种行为列入“做了可能受罚”的范围；这描述规则上的后果，还没有说处罚已经发生。','英语 punish + -able，在中古英语时期已有形式；-able 在这里表示可能、应当受到某种处理。',A(PU,'英语 punish + -able → punishable','可被处罚的；按规则应受处罚的'),'常见 punishable by a fine，以罚款处罚；punishable offence 是可处罚的违法行为。它说明某种行为在规则中被列为应受处罚。','punishable by a fine；a punishable offence；punishable under the rules。','punishable 是具有受罚可能或规定后果；punished 是已经受罚。',('Under the game’s rules, that move is punishable by a loss of points.','按这个游戏的规则，那一步操作可被罚分。'),('The guide explains which violations are punishable.','指南说明了哪些违规行为会受到处罚。'),sources=[S('punishable'),M('punishable')]),
E('impunity','/ɪmˈpjuːnəti/','不受惩罚；逃过追究；不受不利后果','行为发生了，代价却没有落到行为人头上；with impunity 常让人想到“做了也没人追究”。','经法语 impunité 或直接借自拉丁 impunitas／impunitatem，来自 impunis“不受处罚”。im- 是 in- 的否定同化形式，不是“向里”。',IP+[['拉丁 impunitas → 法语 impunité／直接借入 → 英语 impunity','不受惩罚的状态；不受追究']],'act with impunity 是做了也不受罚，常用于批评有权势者逃过责任。较宽泛用法也可指没有付出代价，但不表示行为本身已获道德认可。','act with impunity；a culture of impunity；end impunity。','immunity 常指对疾病或某些责任的免疫、豁免；impunity 直接围绕做某事而没有遭到惩罚或不利后果。',('The report criticised a culture in which powerful people acted with impunity.','报告批评了一种有权势者做事不受追究的风气。'),('The novel’s villain believes he can break every rule with impunity.','小说里的反派觉得，自己违背任何规则都不会受罚。'),sources=[S('impunity'),M('impunity')]),
E('penitentiary','英 /ˌpenɪˈtenʃəri/；美 /ˌpenəˈtenʃəri/','监狱〔尤美式〕；负责特定告解事务的教士','这个词把监禁场所与“反省、悔改”的旧观念联系起来；今天通常直接表示监狱，不代表里面每个人都已经悔悟。','接中世纪拉丁 penitentiarius／penitentiaria，基础是拉丁 paenitentia“悔改”。早期有教会人员、处所等意义；现代监狱义与 penitentiary house 的缩略有关。',RI+[['中世纪拉丁 penitentiarius／penitentiaria → 中古英语 penitenciarie','与忏悔有关的人、处所或机构'],['英语 penitentiary house；后简称 penitentiary','以惩处、改造等为目标的监禁场所 → 监狱']],'在美国英语中常见 state penitentiary、federal penitentiary。教会里的 penitentiary 也能指获授权处理特定告解事务的教士；不能把所有出现都译成“监狱”。','a state penitentiary；a federal penitentiary；the prison／penitentiary system。','prison 是更通用的监狱名称；penitentiary 带特定历史和美式用法。pen“监狱”可作它的俚语简称。',('The old penitentiary now houses a museum.','那座旧监狱如今成了一家博物馆。'),('The historian studied letters written by people held in the penitentiary.','历史学家研究了关押在该监狱里的人写下的信。'),sources=[S('penitentiary'),M('penitentiary')]),
E('penance','/ˈpenəns/','补赎；赎罪行为；作为弥补而做的苦差','不只嘴上说后悔，还做一些事情来表达悔意、弥补过失；宗教传统里可以是祈祷等被安排的行动。','经古法语 peneance、盎格鲁法语及中古英语 penaunce，来自拉丁 paenitentia。与 penitence 是同一个拉丁名词沿不同形式进入英语。',RI+[['古法语 peneance → 中古英语 penaunce → penance','悔改、补赎；表达悔意的行为']],'do penance 是作补赎。现代也会轻松地说 as penance for being late“把这当作迟到的补偿”，不一定有宗教仪式。某些基督宗派的 Penance 还指相关圣事。','do penance；as penance for something；an act of penance。','penitence 侧重心里的悔恨；penance 常侧重表达悔意、补过的行动。punishment 可以由外部强加，不一定伴有悔意。',('He washed the dishes as penance for missing his turn the night before.','前一晚该他洗碗却没洗，这次他补洗，算是赔罪。'),('The novel describes a pilgrim performing an act of penance.','小说描写了一个朝圣者作补赎的情景。'),sources=[S('penance'),M('penance')]),
E('punisher','英 /ˈpʌnɪʃə/；美 /ˈpʌnɪʃər/','施罚者；惩罚者','同一件错事，有受罚的一方，也有实施处罚的一方；-er 把人放在“施罚”这一侧。','英语 punish + -er，表示做惩罚动作的人或事物，中古英语时期已有。',A(PU,'英语 punish + -er → punisher','施加惩罚的人、角色或事物'),'可以用于故事人物、教育或权力关系的讨论。它强调角色功能，不是 judge“法官”或 executioner“行刑者”的精确同义词。大写作品名也保留这个普通词的意思。','the role of punisher；a harsh punisher；judge and punisher。','punisher 是施罚者；the punished 指受罚的人，方向相反。',('The teacher wanted to be a guide rather than a constant punisher.','老师想成为引导者，而不是总在施罚的人。'),('The story gives the same character the roles of accuser and punisher.','故事让同一个角色既负责指控，又负责施罚。'),sources=[S('punisher'),M('punisher')]),
E('penalize','/ˈpiːnəlaɪz/，亦读 /ˈpenəlaɪz/','处罚；使吃亏；置于不利地位','给一个违规动作扣分，或者一种安排让某类人无缘无故少了机会；两者都让对方承担了不利后果。','近代英语 penal + -ize。可联系 penalty 的处罚义来记，但不是直接把 penalty 词尾换掉；英式也常写 penalise。',A(PL,'英语 penal + -ize → penalize','施加处罚；让某人处于不利地位'),'penalize someone for breaking a rule 是因违规处罚。a system that penalizes beginners 则可能批评制度让新手吃亏，并没有说新手犯错。','penalize someone for something；unfairly penalize；penalize an infringement。','punish 一般更直接说惩罚；penalize 常用于罚分、规则处罚，也常用于无过错却受不利影响的场景。',('The referee penalized the player for holding an opponent.','裁判因那名球员拉拽对手而对其作出处罚。'),('The new schedule would penalize staff who depend on buses.','新排班会让依赖公交出行的员工吃亏。'),sources=[S('penalize'),M('penalize')]),
E('penitent','英 /ˈpenɪtənt/；美 /ˈpenətənt/','悔悟的；悔罪者','一个人低下头，不只是因为被发现，而是承认自己的行为伤害了别人，真心想改。','来自法语 pénitent 或直接接拉丁 paenitens／paenitentem，即 paenitere“后悔”的现在分词。更早或联系 paene“几乎”，不宜径直当作 poena 的确定派生。',RT,'a penitent apology 是带真切悔意的道歉；a penitent 也可指悔罪者，尤其宗教语境中的告解、补赎者。语气比 sorry 更庄重。','a penitent expression；a penitent sinner；a truly penitent apology。','penitent 与 repentant 接近，强调悔意；embarrassed 只是尴尬，未必承认行为有错。',('She returned with a penitent expression and an honest apology.','她带着悔悟的神情回来，真诚地道了歉。'),('The priest listened quietly to the penitent.','神父静静地听那位悔罪者倾诉。'),sources=[S('penitent'),M('penitent')]),
E('penitence','英 /ˈpenɪtəns/；美 /ˈpenətəns/','悔恨；悔罪之心','把 penitent 的人放到心里看：真正让他难受的，是意识到自己做错了；这种悔意就是 penitence。','经古法语 penitence 并可直接接拉丁 paenitentia。现代 penitent + -ence 的联系便于记忆，历史上名词有自己的借入路线。',RI+[['古法语 penitence／直接拉丁借入 → 中古英语 penitence','悔恨、悔罪的状态；心里的反省']],'show penitence 是表现悔意，in penitence 可形容带着忏悔的态度。这个词偏正式或宗教，不只是一般对倒霉结果的遗憾。','show genuine penitence；an expression of penitence；in penitence。','penitence 是悔意；penance 是表达悔意、弥补过失的行动。行动可以看见，内心是否真诚仍要结合行为理解。',('Her letter expressed genuine penitence for the harm she had caused.','她在信中表达了对自己所造成伤害的真诚悔意。'),('The scene contrasts public punishment with private penitence.','这一幕把公开受罚与内心悔恨作了对照。'),sources=[S('penitence'),M('penitence')]),
E('impune','构词读法 /ɪmˈpjuːn/〔古旧词〕','未受惩罚的〔古旧〕','事情做了，处罚却没有落下来；这个罕用旧词把“不受罚”直接作为形容词说出来。','学术式借自拉丁 impunis，来自否定 in- 与 poena 这一处罚词族；im- 表不。英语 impunity 是从相应拉丁名词另行借入，不必从 impune 往后推。',A(IP,'英语 impune〔古旧形容词〕','未受处罚的；现代通常用 unpunished'),'今天主要用于识别旧文，普通写作直接说 unpunished 更自然。网上有些 impune 是 impugn“质疑、抨击”的误拼；不能用这些误拼例子反过来定义本词。','remain impune〔古旧〕；go unpunished〔现代常用〕。','impune 是旧形容词“不受罚的”；impugn 是动词“质疑、攻击其可信度”，虽然发音接近，词源和语法都不同。',('The glossary defines “impune” as “unpunished.”','词汇表把 impune 解释为“未受惩罚的”。'),('In a modern edition, “remain impune” could be replaced with “go unpunished.”','在现代版本中，remain impune 可以改写为 go unpunished。'),sources=[S('impune'),K('impune'),'https://www.wordnik.com/words/impune']),
]
W += [
E('painful','/ˈpeɪnfəl/','疼痛的；令人痛苦的；难堪的','有的痛落在身体上，有的落在回忆或尴尬场面里；painful 都从“让人难受”这一点展开。','中古英语已有 paynful 等形式，等于 pain + -ful。-ful 在此表示带来或充满某种感受，不是把一份 pain 真正装满容器。',A(P+[['古法语 peine → 中古英语 peyne','痛苦、费力']], '中古英语 paynful → 英语 painful','充满痛苦、造成痛苦的'),'a painful knee 是疼痛的膝盖，a painful memory 是让人难受的回忆，a painful silence 则可能是难堪的沉默。它常修饰造成痛感或痛苦的部位、事件、经历。','a painful injury；a painful memory；a painful decision；painful to watch。','painful 往往指让人难受的事物；pained 常指人显出的难受神情。a pained expression 是难受的表情，a painful experience 是令人痛苦的经历。',('Walking up the stairs was painful after the long hike.','长途徒步后，上楼梯都很疼。'),('It was painful to admit that the plan had failed.','承认计划已经失败，让人很难受。'),sources=[K('painful'),M('painful')]),
E('painfully','/ˈpeɪnfəli/','痛苦地；令人难堪地；极其〔常含不快感〕','把慢、明显或害羞推到让人难受的程度：painfully slow 是慢得折磨人，而不一定伴有身体疼痛。','中古英语已有相应副词形式，来自 painful + -ly；继承身心痛苦义，又发展为带不快色彩的程度强调。',A(PA,'英语 painful + -ly → painfully','带着痛苦；达到令人难受的程度'),'painfully aware 是清楚意识到某件不好受的事；painfully shy 是害羞得让人难受。它可以表达真实痛感，也可以是对程度的生动评价。','painfully slow；painfully obvious；painfully aware of；painfully shy。','very 是中性的程度词；painfully 往往暗示这种程度造成难受、尴尬或挫折。',('The download was painfully slow.','下载慢得让人难受。'),('She was painfully aware that everyone had heard her mistake.','她难堪地意识到，每个人都听见了她说错的话。'),sources=[K('painfully'),M('painfully')]),
E('painless','/ˈpeɪnləs/','无痛的；轻松顺利的；不费事的','原来担心会疼或很麻烦，结果几乎没有不适；这里的“无痛”常从身体感觉借到办事体验。','中古英语 paynles／peynlees，等于 pain + -less“不具有”。不是“痛得少一点”的比较级。',A(P+[['古法语 peine → 中古英语 peyne','痛苦']], '中古英语 paynles → 英语 painless','没有痛感；比喻没有明显麻烦、负担'),'a painless procedure 可以指没有痛感的操作，a painless upgrade 则说升级过程省心。广告里的 painless 可能带夸张，应从实际语境理解程度。','a painless procedure；a painless transition；a painless way to do something。','painless 指过程没有疼痛或麻烦；painkilling 指具有缓解疼痛的作用，不保证整个经历完全无痛。',('The software update was quick and painless.','软件更新又快又省心。'),('The small scratch was painless by the next morning.','到了第二天早上，那处小擦伤已经不疼了。'),sources=[K('painless'),M('painless')]),
E('painlessly','/ˈpeɪnləsli/','无痛地；轻松顺利地','事情完成了，却没有原先担心的疼痛、折腾或阻力；它描述完成过程给人的感受。','英语 painless + -ly，副词继承 pain + -less“没有痛苦”的意义。',A(PA,'英语 painless + -ly → painlessly','以不造成疼痛或麻烦的方式'),'switch painlessly 是顺利切换，remove something painlessly 可说去除过程中不疼。比喻用法很常见，不必每次都译成医学式的“无痛地”。','switch painlessly；transfer painlessly；as painlessly as possible。','easily 强调不难；painlessly 更突出没有不适或折腾，可能是对原先担忧的回应。',('We moved the files to the new computer painlessly.','我们很顺利地把文件转到了新电脑上。'),('The team tried to make the transition happen as painlessly as possible.','团队尽量让过渡过程少些折腾。'),sources=[K('painlessly'),M('painless')]),
E('pained','/peɪnd/','痛苦的；难堪的；流露不快的','听见令人失望的话，脸上轻轻一僵、勉强挤出笑容；pained 特别适合这种显露出来的难受。','英语动词 pain + -ed，表示受到痛苦影响的状态；pain 动词有法语 pener 借入和英语名词派生的背景。',A(PV,'英语 pain + -ed → pained','被刺痛、心里难受；表现出痛苦或不快'),'a pained expression、a pained smile 都常见。I was pained to hear... 表示听说某事令我难过，语气较正式；这个词不只说身体伤痛。','a pained look；a pained expression；be pained by；be pained to hear。','pained 往往是承受痛苦的一方；painful 通常是带来痛苦的东西或体验。',('He gave a pained smile when the old argument began again.','旧争论又开始时，他勉强露出一个难受的笑容。'),('She was pained to hear that the library would close.','听说图书馆将关闭，她很难过。'),sources=[S('pain'),M('pained')]),
E('painstaking','英 /ˈpeɪnzˌteɪkɪŋ/；美常读 /ˈpeɪnˌsteɪkɪŋ/，亦读 /ˈpeɪnzˌteɪkɪŋ/','细致认真的；煞费苦心的','别人嫌麻烦略过去的小细节，他愿意停下来一一核对；核心是肯付出工夫，把事情做仔细。','来自 pains“费心、努力”+ taking，联系 take pains。不是 pain + staking“把痛押上去”；美式清音 /s/ 不改变这个实际构词来源。',PA+[['英语 take pains；pains + taking','费心、下工夫'],['painstaking：先作勤勉劳动之名，后作形容词','投入细致工夫的；认真周密的']],'painstaking research 是仔细查证的研究，painstaking restoration 是不放过细节的修复。通常是正面评价；不一定要慢，更不是指研究者真的身体疼。','painstaking work；painstaking research；a painstaking reconstruction。','painful 强调痛苦；painstaking 强调费心和细致。困难工作可能两者都有，但不能互相替代。',('The map was the result of years of painstaking research.','这张地图是多年细致研究的成果。'),('She made a painstaking copy of every damaged inscription.','她把每一处受损铭文都仔细摹录下来。'),sources=[S('painstaking'),M('painstaking'),K('painstaking')]),
E('painstakingly','英 /ˈpeɪnzˌteɪkɪŋli/；美常读 /ˈpeɪnˌsteɪkɪŋli/','细致地；煞费苦心地','一颗颗珠子重新穿回去，一行行旧字重新辨认；它把注意力放在做事时耐心处理细节的方式上。','英语 painstaking + -ly，底层仍是 pains + taking“肯费工夫”，不是 pain + staking。',PA+[['英语 take pains → painstaking','愿意投入细致工夫'],['英语 painstaking + -ly → painstakingly','一丝不苟地、耐心细致地']],'常修饰 restore、reconstruct、record、check 等需要细节工作的动词。painstakingly checked 表示仔细核过，不仅仅是花了很长时间。','painstakingly restore；painstakingly reconstruct；painstakingly record details。','slowly 只说速度慢；painstakingly 说明慢背后可能有认真处理细节的努力。',('The conservator painstakingly cleaned each tile.','修复师仔细清理了每一块瓷砖。'),('They painstakingly reconstructed the route from old letters.','他们从旧信件中一点点认真还原了当年的路线。'),sources=[S('painstaking'),K('painstakingly'),M('painstaking')]),
E('punished','/ˈpʌnɪʃt/','受过处罚的；被惩罚的；处罚了','处罚已经实施，而不只是写在规则里；这个形式把视角放到已发生的动作或受罚状态上。','英语 punish + -ed，词尾紧接清辅音 /ʃ/，所以 -ed 读 /t/，不另添一个音节。',A(PU,'英语 punish + -ed → punished','施加了处罚；已经受罚的'),'was punished for 是因某事受到处罚；have been punished 强调已经受罚。用作过去式时，谁是施罚者要看主语，不能见到 -ed 就总译为被动。','be punished for something；those punished；have already been punished。','punished 说实际受罚；punishable 说按规则可受罚。punishing 则是主动造成痛苦或极其艰苦的。',('The player was punished for deliberately breaking the rule.','那名球员因故意违规受到了处罚。'),('The story asks whether everyone who was punished was actually responsible.','故事追问：每一个受罚的人，真的都有责任吗？'),sources=[K('punished'),S('punish')]),
E('punishing','/ˈpʌnɪʃɪŋ/','极其艰苦的；严酷的；正在惩罚','日程密到几乎没有喘气机会，或烈日晒得人筋疲力尽；这些事像是在“惩罚”身体，所以叫 punishing。','英语 punish + -ing，从正在施加处罚的动作，引出造成强烈负担的形容词用法。',A(PU,'英语 punish + -ing → punishing','正在处罚；让人吃尽苦头、难以承受的'),'a punishing schedule 是极累人的日程，punishing heat 是难熬的酷热。语义重点通常是承受者很辛苦，不一定有人存心惩罚。','a punishing schedule；a punishing climb；punishing heat。','punitive 强调惩罚性目的；punishing 强调实际感受严酷。一个行程可以很 punishing，却完全不是处罚。',('The team faced a punishing schedule of three matches in four days.','球队面临四天三场比赛的严酷赛程。'),('We climbed the final slope in punishing heat.','我们顶着难熬的酷热爬上了最后一段坡。'),sources=[S('punishing'),M('punishing')]),
E('unpunished','/ʌnˈpʌnɪʃt/','未受惩罚的；未被追究的','错误或恶行发生了，但处罚这一环没有跟上；un- 把“已经受罚”的状态否定掉。','英语 un- 不 + punished。它不表示把已经执行的处罚倒回去，而表示没有受到处罚。',A(PU,'英语 punish → punished；un- + punished → unpunished','未受处罚的；行为未被追究的'),'go unpunished、remain unpunished 很常见，既可说人，也可说某种违法或违规行为没有受到追究。没有受罚不等于被证明没有做错。','go unpunished；remain unpunished；leave an offence unpunished。','unpunished 说某人或某件事没有受罚；impunity 说不受追究的状态、处境，常用 with impunity。',('The cheating did not go unpunished.','那次作弊没有逃过处罚。'),('The report asked why serious violations had remained unpunished.','报告追问，为什么严重违规一直没有受到追究。'),sources=[K('unpunished'),'https://dictionary.cambridge.org/us/pronunciation/english/unpunished']),
E('punitively','英 /ˈpjuːnɪtɪvli/；美 /ˈpjuːnətɪvli/','惩罚性地；苛刻得像处罚一样地','回应一个错误时，重点是让对方吃苦头；用来修饰高额收费，又常表示高得令人觉得像挨罚。','英语 punitive + -ly，继承 punitive 的惩罚性或苛重意味。',A(PT,'英语 punitive + -ly → punitively','以惩罚为目的、带有惩罚作用地'),'respond punitively 是以惩罚方式回应；punitively high charges 是苛重的收费。副词不是“受到惩罚地”，它通常描述做法或措施。','respond punitively；act punitively；punitively high fees。','punishingly 常强调难熬的程度；punitively 更突出措施像在处罚人，二者有时重叠但视角不同。',('The supervisor responded punitively to an honest mistake.','面对一次无心之失，主管却采取了惩罚性的回应。'),('Critics said the cancellation charges were punitively high.','批评者认为取消费用高得近乎惩罚。'),sources=[M('punitive'),K('punitively')]),
E('repentance','/rɪˈpentəns/','悔改；忏悔','一个人不只回忆错误时难受，还愿意把生活的方向改过来；repentance 把这份悔意与转变作为整体来讲。','经古法语 repentance 借入，由 repentir 的分词词干形成。现代可拆 repent + -ance，但名词有法语阶段，不能直接当英语新造。',RF+[['古法语 repentance → 中古英语 repentaunce → repentance','悔恨、悔改的状态或过程']],'genuine repentance 是真诚悔改，a sign of repentance 是悔改迹象。在宗教语境中常包含对罪的反省和生活转向；日常也可说为自己的严重过失后悔。','sincere repentance；show repentance；repentance for wrongdoing。','regret 范围更广，可能只是后悔损失或机会；repentance 通常围绕自己认为做错的事，并指向改过。',('His repayment was one sign of genuine repentance.','他把钱还回来，是他真心悔改的一个迹象。'),('The sermon linked repentance with a change in conduct.','布道把悔改与行为上的改变联系起来。'),sources=[S('repentance'),M('repentance')]),
E('repentant','/rɪˈpentənt/','悔过的；后悔并想改正的','做错之后回到对方面前，承认伤害、愿意修复；repentant 描述的是这种人的态度。','经古法语 repentant，原是 repentir“悔改”的现在分词。英语该形容词记录早于动词 repent，现代 repent + -ant 的拆法不能当作实际先后顺序。',RA,'a repentant offender 是有悔意的犯错者，a repentant tone 是悔悟的语气。它比简单 sorry 更强调对自身行为的反省，常用于正式叙述。','a repentant offender；a repentant expression；sound genuinely repentant。','repentant 和 penitent 意思接近；apologetic 强调表示歉意，是否真有深刻悔改还要看行为。',('He sounded repentant and offered to repair the damage.','他听起来很有悔意，并提出弥补损失。'),('The letter came from a repentant former friend.','那封信来自一个心怀悔意的旧友。'),sources=[S('repentant'),M('repentant')]),
E('unrepentant','/ˌʌnrɪˈpentənt/','不悔改的；毫不后悔的','别人要求他为某事低头，他却仍然说“我不后悔”；有时是顽固，有时只是轻松地坚持自己的爱好。','英语 un- 不 + repentant，中古英语时期已有相应形式；否定的是悔改态度。',A(RA,'英语 un- + repentant → unrepentant','没有悔意；仍坚持原来的做法或偏好'),'an unrepentant liar 通常是批评；an unrepentant coffee lover 则可以幽默地说自己就是爱喝咖啡。词的严厉程度取决于被坚持的是什么。','remain unrepentant；an unrepentant offender；an unrepentant fan。','unpunished 表示没有受罚；unrepentant 表示没有后悔。一个人可以已经受罚却依然不悔改。',('He remained unrepentant even after admitting that he had lied.','即使承认自己撒了谎，他仍毫无悔意。'),('She is an unrepentant fan of old detective novels.','她就是坚定不移地喜欢老侦探小说。'),sources=[S('unrepentant'),M('unrepentant')]),
E('penitential','英 /ˌpenɪˈtenʃəl/；美 /ˌpenəˈtenʃəl/','忏悔的；补赎的；忏悔规程书','祈祷、斋戒或一段文字，是为了表达悔意、作补赎；penitential 把这种宗教或反省目的说出来。','经古法语 penitencial 或直接接中世纪拉丁 penitentialis，来自 paenitentia。不是简单在英语 penitent 后随意加 -ial。',RI+[['中世纪拉丁 penitentialis → 古法语 penitencial／直接借入 → 英语 penitential','与忏悔、补赎有关的'],['英语名词 a penitential','历史上列明罪过与相应补赎的规程书']],'penitential prayers 是忏悔祷文，penitential discipline 是相关悔罪修持。历史研究中的 a penitential 可是一本文献，不是“一个悔罪的人”；后者是 a penitent。','penitential prayers；penitential practices；a medieval penitential。','penitent 常形容人有悔意；penitential 常形容表达悔意的活动、文字或制度。penitentiary 现代主要是监狱或特定教会职位。',('The service included several penitential prayers.','礼拜中包括了几段忏悔祷文。'),('The historian translated a medieval penitential.','历史学家翻译了一本中世纪的补赎规程书。'),sources=[S('penitential'),M('penitential')]),
E('penitently','英 /ˈpenɪtəntli/；美 /ˈpenətəntli/','悔恨地；带着悔意地','说话的音量放低，态度认真，不再忙着给自己找理由；penitently 描述这种带着悔悟的表达方式。','英语 penitent + -ly；它从人的悔悟状态转为动作所表现的态度。',A(RT,'英语 penitent + -ly → penitently','表现出悔恨、悔罪地'),'apologize penitently 是真有悔意地道歉，bow one’s head penitently 是带着悔恨低头。比 sadly“悲伤地”更具体，常有自己做错的背景。','speak penitently；apologize penitently；look penitently at someone。','sadly 可以因为任何悲伤原因；penitently 特别指对自己的过错有悔意。',('“I should have listened,” he said penitently.','“我当时应该听你的，”他悔恨地说。'),('She penitently admitted that she had blamed the wrong person.','她带着悔意承认，自己错怪了别人。'),sources=[M('penitent'),K('penitently')]),
E('impenitent','英 /ɪmˈpenɪtənt/；美 /ɪmˈpenətənt/','不悔改的；顽固不认错的','已经知道自己伤害了别人，却仍不肯承认需要改变；这是比较正式、带批评意味的“不思悔改”。','来自拉丁 impaenitens／impaenitentem：否定 in- 在 p 前成为 im-，加 paenitens“悔悟的”。英语借入整词，现代才可直观看成 im- + penitent。',R+[['拉丁 paenitens → in- + paenitens → impaenitens','悔悟的 → 不悔悟的'],['英语 impenitent','不悔改的；也可作名词指不悔罪者']],'常见于宗教、道德评价或文学叙述。它说没有悔意，不是说没有受到惩罚；也不只是坚持一个与别人不同的意见。','an impenitent offender；remain impenitent；an impenitent response。','impenitent 与 unrepentant 很接近，前者往往更庄重、更有宗教或道德评判色彩。',('The character remains impenitent despite the harm he has caused.','那个角色尽管造成了伤害，却仍不思悔改。'),('Her impenitent reply disappointed those who had hoped for an apology.','她毫无悔意的回答，让那些盼着她道歉的人失望了。'),sources=[S('impenitent'),M('impenitent')]),
E('impenitence','英 /ɪmˈpenɪtəns/；美 /ɪmˈpenətəns/','不悔改；顽固不认错的态度','不是某一句嘴硬的话，而是持续不肯承认过错、不想改变的状态；-ence 把态度作为一个名词来讨论。','借自晚期拉丁 impaenitentia，基础是 impaenitens“不悔悟的”。可与英语 impenitent 联系理解，但名词的历史来源单独成立。',R+[['拉丁 in- + paenitens → impaenitens → 晚期拉丁 impaenitentia','不悔悟的 → 不悔改的状态'],['英语 impenitence','无悔意、拒不悔改']],'常用于正式评论、宗教论述和文学人物分析。the impenitence of the speaker 不是“说话者受到的处罚”，而是他不肯反省的态度。','show impenitence；persistent impenitence；an attitude of impenitence。','impunity 是不受罚，impenitence 是不悔改。外在后果与内心态度是两条不同的轴。',('The novel treats his impenitence as a greater failing than his first mistake.','小说把他不思悔改看成比最初的错误更大的缺点。'),('The apology was undermined by the impenitence of his later remarks.','他后来的话毫无悔意，让先前的道歉失去了分量。'),sources=[S('impenitence'),M('impenitence')]),
E('penalization','英 /ˌpiːnəlaɪˈzeɪʃən/；美 /ˌpiːnələˈzeɪʃən/','处罚；使处于不利地位；罚项处理','把“给某种行为或选择附加代价”这件事作为过程来谈；评分里扣分，模型里加罚项，都有这个共同画面。','英语 penalize + -ation，形容词 penal 先派生动词，再形成过程名词；也写 penalisation。',A(PL,'英语 penalize → penalization','施加处罚或额外代价的过程'),'普通语境说处罚，建模语境可说给过度复杂的模型增加代价，以免一味追求拟合训练数据。后一用法是数学评价规则，不是在道德上“责罚模型”。','penalization of errors；unfair penalization；a penalization term。','penalty 常是具体的处罚、代价或罚项；penalization 更侧重施加这种代价的做法。',('The policy aims to prevent unfair penalization of part-time staff.','这项政策旨在避免兼职员工受到不公平的不利对待。'),('The scoring system includes penalization for unnecessary complexity.','这个评分系统会对不必要的复杂程度施加罚项。'),sources=[M('penalize'),K('penalization'),'https://scikit-learn.org/stable/modules/linear_model.html']),
E('nonpunitive','英 /ˌnɒnˈpjuːnɪtɪv/；美 /ˌnɑːnˈpjuːnətɪv/','非惩罚性的','发现错误后，先弄清原因、修复流程，而不是把主要精力放在让某个人吃苦头；这种取向可叫 nonpunitive。','英语 non- 非、不 + punitive，表示措施不以惩罚为目的或不包含惩罚性作用。',A(PT,'英语 non- + punitive → nonpunitive','不施加、包含或着眼于惩罚的'),'a nonpunitive response 可以是培训、支持或改进流程。它不等于完全不管，也不意味着所有行为都没有后果；关键是所说措施的目的与方式。','a nonpunitive approach；nonpunitive measures；a nonpunitive reporting system。','nonpunitive 形容处理方式；unpunished 说明某事没有受罚。前者关注措施性质，后者关注结果。',('The team adopted a nonpunitive approach to reporting routine mistakes.','团队采用了非惩罚性的方式，鼓励报告日常差错。'),('The workshop offered nonpunitive ways to address classroom conflict.','工作坊介绍了以非惩罚方式处理课堂冲突的办法。'),sources=[M('nonpunitive'),K('nonpunitive')]),
E('painkiller','英 /ˈpeɪnˌkɪlə/；美 /ˈpeɪnˌkɪlər/','止痛药；缓解疼痛的东西','把 pain 当作要压下去的感觉，killer 在这个复合词里表示消除、缓解它的东西，日常多指药物。','英语 pain + killer；killer 来自动词 kill + -er。把拉丁来源的 pain 与英语词组成现代复合词，不存在一个对应的古拉丁整词。',A(PA,'英语 pain + killer → painkiller','缓解疼痛的东西；常指止痛药'),'这是日常词，医学上的 analgesic 更专业。painkiller 说的是缓解疼痛的作用，不自动说明能消除造成疼痛的病因，也不是所有药品的统称。','take a painkiller；a prescribed painkiller；painkiller use。','painkiller 是药物或其他缓痛手段的名词；painkilling 是“具有止痛作用”的形容词；painless 是过程或状态无痛。',('The nurse recorded which painkiller the patient had been given.','护士记录了病人已经使用哪一种止痛药。'),('The leaflet explains that a painkiller relieves pain.','说明页解释说，止痛药的作用是缓解疼痛。'),sources=[M('painkiller'),K('painkiller'),'https://www.cancer.gov/publications/dictionaries/cancer-terms/def/analgesic']),
E('painkilling','/ˈpeɪnˌkɪlɪŋ/','止痛的；缓解疼痛的','不是给东西取名，而是在描述它起什么作用：它能把疼痛减轻，所以有 painkilling effect。','英语 pain + killing，kill 在此取消除、压低的比喻义；与 painkiller 平行构成名词和形容词表达。',A(PA,'英语 pain + killing → painkilling','具有缓解疼痛作用的'),'painkilling medicine 是止痛药，painkilling effect 是镇痛作用。它说一种作用，不保证完全没有任何痛感；也不等于 sedative“镇静的”。','painkilling medication；a painkilling effect；painkilling properties。','painkilling 表示缓解疼痛的作用；painless 表示没有痛感的状态。一个过程用了止痛措施，也不必因此叫完全 painless。',('The study measured the treatment’s painkilling effect.','研究测量了这种治疗的镇痛效果。'),('The label describes the medicine’s painkilling properties.','标签介绍了这种药物的止痛作用。'),sources=[M('painkiller'),K('painkilling'),'https://www.cancer.gov/publications/dictionaries/cancer-terms/def/analgesic']),
]
ROOT=dict(id='C0989',meaning='处罚、代价、痛苦；另附悔恨支线',core='poena 先让人想到犯错后要付出的代价，逐渐延伸到承受的痛苦。由此能理解 penalty 的处罚、pain 的疼痛，以及 punish 的施罚。悔恨支线则把目光转向“我认识到自己做错了”。',image='三件事分开看：规则规定的代价是 penalty，承受的不适是 pain，心里的悔恨是 penitence。它们在生活中可能相连，历史词源却不能因此全部画成一条确定直线。',intro='主要来源是拉丁 poena“处罚、代价”，远接希腊 poinē；punire 是相关动词。原表并入的 repent、penitent 等出自 paenitere“后悔”，其更早来源有分歧，或联系 paene“几乎”。这里保留为单独的关联学习支线，不断言它必由 poena 发展而来。pine 只把“憔悴、苦思”动词列入可能联系，松树义另源。',forms='pen- 见 penal、penalty；poen- 仍见 subpoena；pun- 见 punish、punitive、impunity。pain 经法语音形变化而来。penit-、repent- 属 paenitere 悔恨支线；不要因 pen 字母相似，把 pen“钢笔”或 repent“匍匐的”也并进来。',branches=[['痛苦与缓解','pain, painful, painfully, painless, painlessly, pained, painkiller, painkilling'],['从吃苦到费心、思念','painstaking, painstakingly, pine'],['规则上的处罚与代价','penalty, penal, penalize, penalization, subpoena'],['施罚与受罚','punish, punishment, punisher, punished, punishable, punishing, punitive, punitively, nonpunitive'],['没有受到追究','impunity, impune, unpunished'],['关联支线：悔改与补赎','repent, repentance, repentant, unrepentant, penitent, penitently, penitence, penance, penitential, penitentiary, impenitent, impenitence']],contrasts='painful 让人痛苦，pained 显得痛苦，painstaking 肯费心做细致工作。punitive 强调惩罚目的，punishing 强调严酷难熬。unpunished 没有受罚，unrepentant 没有悔意。penitence 是悔意，penance 是补赎行动；这一组的早期词源与 poena 关系未定。',practice='He was punished, but he remained unrepentant. 他已经受罚，却依然没有悔意。再比较 painstaking work 与 painful work：前者强调认真细致，后者强调工作让人痛苦。',words=[],exclude={})
if __name__=='__main__':
    m=json.loads((BASE/'.cache/batch200/rewrite_vid.json').read_text());r=next(r for r in m['roots'] if r['id']==ROOT['id'])
    ROOT['words']=[w for w in r['family'] if '-' not in w]
    expected=set(ROOT['words'])&set(m['owned_words']);actual={e['word'] for e in W}
    assert expected==actual,(expected-actual,actual-expected)
    assert len(W)==len(actual) and all(len(e['examples'])>=2 and len(e['history'])>=2 for e in W)
    OUT.mkdir(parents=True,exist_ok=True)
    (OUT/'roots_batch200_vid_25.json').write_text(json.dumps([ROOT],ensure_ascii=False,indent=2))
    (OUT/'words_batch200_vid_25.json').write_text(json.dumps(W,ensure_ascii=False,indent=2))
    print('pen:',len(W),'words;',sum(len(e['examples']) for e in W),'examples;',len(ROOT['words']),'references')
